input.command:
set -e
/tmp/sc_venv/bin/pip install -q pglast 2>&1 | grep -v notice || true
M=/tmp/pgmock; rm -rf $M; mkdir -p $M/bin $M/work $M/sql
cat > $M/bin/psql <<'EOF'
#!/usr/bin/env bash
# mock psql: records SQL, answers by pattern. $1 = conninfo (src or dst)
conn="$1"; shift; sql=""; single=0
while (( $# )); do case "$1" in -c) sql="$2"; shift;; --single-transaction) single=1;; esac; shift; done
n=$(ls /tmp/pgmock/sql | wc -l | tr -d ' ')
if (( single )); then cat > /tmp/pgmock/restore_stream.sql; echo "$conn RESTORE-STREAM" >> /tmp/pgmock/calls.log; exit 0; fi
printf '%s' "$sql" > "/tmp/pgmock/sql/$(printf %03d "$n").sql"
echo "$conn -c <$n>" >> /tmp/pgmock/calls.log
is_src=0; [[ "$conn" == *src* ]] && is_src=1
case "$sql" in
  *server_version_num*)            echo 16 ;;
  *"from pg_namespace where"*)     echo 1 ;;
  *to_regclass*)                   if (( is_src )); then echo public.users; else [[ "${MOCK_DST_HAS_TABLE:-0}" == 1 ]] && echo public.users || echo ""; fi ;;
  *"relkind='p'"*)                 echo "" ;;
  *"bt.typtype <> 'e'"*)           echo "${MOCK_UTYPES:-}" ;;
  *"CREATE TYPE"*)                 echo "CREATE TYPE public.order_status AS ENUM ('new', 'paid');" ;;
  *"bt.typtype='e'"*)              echo "public.order_status" ;;
  *"join pg_extension e on"*)      echo "citext" ;;
  *"from pg_extension where"*)     echo 1 ;;
  *"not (rn.nspname"*)             echo "${MOCK_OUTBOUND:-}" ;;
  *"not (cn.nspname"*)             echo "${MOCK_INBOUND:-}" ;;
  *pg_trigger*)                    echo "" ;;
  *pg_policy*)                     echo "" ;;
  *hashtext*)                      if (( is_src )); then echo "42 rows, hash 1234"; else echo "${MOCK_DST_HASH:-42 rows, hash 1234}"; fi ;;
  *pg_indexes*)                    echo 3 ;;
  *"from pg_constraint where conrelid"*) echo 2 ;;
  *"dp.deptype in"*)               echo "public.users_id_seq public.orders_id_seq" ;;
  *last_value*)                    echo "42/t" ;;
  *"select count(*) from public."*) echo 42 ;;
  *)                               echo "UNMATCHED: $sql" >&2; exit 3 ;;
esac
EOF
cat > $M/bin/pg_dump <<'EOF'
#!/usr/bin/env bash
[[ "$1" == --version ]] && { echo "pg_dump (PostgreSQL) 16.4 (Homebrew)"; exit 0; }
echo "pg_dump $*" >> /tmp/pgmock/calls.log
for a in "$@"; do [[ "$a" == --file=* ]] && echo "FAKEDUMP" > "${a#--file=}"; done
EOF
cat > $M/bin/pg_restore <<'EOF'
#!/usr/bin/env bash
echo "pg_restore $*" >> /tmp/pgmock/calls.log
[[ "$1" == --list ]] && { echo "; header"; echo "123; 1259 TABLE public users"; exit 0; }
printf 'SET search_path = '"''"';\nCREATE TABLE public.users (id int, status public.order_status);\nCOPY public.users (id, status) FROM stdin;\n1\tnew\n\\.\n'
EOF
chmod +x $M/bin/*
echo "mocks ready"
